// 從 router 轉發過來的 LINE 原始 body 取 replyToken
const body = $input.first().json.body || $input.first().json || {};
const events = body.events || [];
const replyToken = events.length ? (events[0].replyToken || null) : null;
return [{ json: { replyToken } }];

// 讀「上次查詢時間」當篩選起點；沒有就預設今天 00:00（第一次執行或剛部署時的安全預設）
const staticData = $getWorkflowStaticData('global');
const replyToken = $('取 replyToken').first().json.replyToken;
const todayStart = $now.setZone('Asia/Taipei').toFormat('yyyy-MM-dd') + 'T00:00:00+08:00';
const cursor = staticData.lastQueryTime || todayStart;
return [{ json: { replyToken, cursor } }];

// 組工作回報訊息：系統日誌（原本 10 個 LINE 推播全部改記在這）＋ 廣告資料庫今天異動
const replyToken = $('取 replyToken').first().json.replyToken;
const today = $now.setZone('Asia/Taipei').toFormat('yyyy-MM-dd');

const pick = (p, kind) => {
  if (!p) return '';
  if (kind === 'title') return (p.title || []).map(t => t.plain_text).join('');
  if (kind === 'rich') return (p.rich_text || []).map(t => t.plain_text).join('');
  if (kind === 'select') return p.select ? p.select.name : '';
  if (kind === 'url') return p.url || '';
  return '';
};

const logResults = ($('查系統日誌').first().json.results) || [];
const logLines = logResults.map(r => {
  const p = r.properties || {};
  const src = pick(p['來源'], 'select') || '?';
  const title = pick(p['標題'], 'title') || '(無標題)';
  return `・[${src}] ${title}`;
}).join('\n');

const adResults = ($('查廣告異動').first().json.results) || [];
const byStatus = {};
const pubList = [];
for (const r of adResults) {
  const p = r.properties || {};
  const status = pick(p['狀態'], 'select') || '(無狀態)';
  byStatus[status] = (byStatus[status] || 0) + 1;
  if (status === '已發布') {
    const name = pick(p['案名'], 'title');
    const link = pick(p['粉專貼文連結'], 'url');
    pubList.push(`・${name}${link ? '\n　' + link : ''}`);
  }
}
const statusSummary = Object.entries(byStatus).map(([k, v]) => `${k} ${v}`).join('、') || '沒有異動';

let text = `📋 工作回報 ${today}\n\n`;
text += `【廣告動態】${statusSummary}\n`;
if (pubList.length) text += pubList.join('\n') + '\n';
text += `\n【系統事件】${logResults.length ? '（' + logResults.length + ' 筆，含守門員擋下／發文失敗／API 異常等）' : '（今天沒有異常事件）'}`;
if (logResults.length) text += '\n' + logLines;

return [{ json: { replyToken, text: text.slice(0, 4900) } }];

// LINE 回覆成功才推進游標；失敗的話下次查詢還是會抓到這批，不會漏掉
const staticData = $getWorkflowStaticData('global');
staticData.lastQueryTime = $now.toISO();
return $input.all();
